  nc = `Halloween 2022`,
  rc = `Handlar detta event om uppdateringar av ditt spel inför halloween 2022? Om du lägger till nya kartor, skins, illustrationer eller annat innehåll inför halloween, eller kör tidsbegränsade event med särskilt läskigt innehåll, utmaningar eller andra liknande aktiviteter vill vi gärna få reda på det. Vi överväger olika möjligheter till att bättre nå ut med temaevent till en bredare publik, men först behöver vi bilda oss en uppfattning om vilka typer av aktiviteter utvecklare arrangerar i era spel (om några alls) för att uppmärksamma högtiden. Klicka på ”På” nedanför detta event om detta event gäller en uppdatering av ditt spel inför halloween 2019.`,
