  Rx = `Den här versionen syns bara när upplösningen för sidan minskas för visning på mobiler.`,
  zx = `Du kan även uppdatera bibliotekets huvudbild med marknadsföring för uppdatering, tillkännagivande, säsong eller annat event. För att göra detta besöker du fliken Grafiska resurser under administrationen för butikssidan.`,
