  Wx = `Valfri`,
  Gx = `Den här bilden innehåller vanligtvis illustrationer och marknadsföring för ditt event, samt eventuellt kort meddelande du vill bifoga. Steam inkluderar i vissa sammanhang ditt spels namn och ikon bredvid bilden, men du kan även inkludera ditt spels logotyp på din omslagsbild då den bilden används när ditt event delas på sociala media.`,
  Kx = `Det syns på din butikssida under nyliga tillkännagivanden, på listan över event och tillkännagivanden, och på detaljsidan i biblioteket. Den här bilden används för att representera eventet då det delas på sociala media. Bilden bör vara tydlig och igenkännbar då den används för att länka ditt event/tillkännagivande och kanske visas tillsammans med innehåll från andra spel.`,
  qx = `Bilden innehåller för det mesta illustrationer och varumärken som representerar utgivaren, utvecklaren eller franchisen. Steam inkluderar i vissa fall automatiskt din avatar bredvid på bilden.`,
