  rw = `Som standard visar Steam automatiskt alla livesändningar associerade med de spel som finns på denna reasida. Inget behöver göras om denna inställning verkar vettig för denna rea. Men, om du vill bestämma vilka sändningar som syns på reasidan kan du aktivera den flaggan och välja vilka under fliken Sändning.`,
